// sv
import "DPI-C" function int c_checksum(input int data[]);
export "DPI-C" function sv_report;
// c: #include "dpi.h"  int c_checksum(const svOpenArrayHandle data) { ... }
$ xsc -c checksum.c -o checksum.o && xsc --shared checksum.o -o checksum.so
$ xvlog -sv tb.sv && xelab -sv_lib checksum -debug typical tb -s tbsim && xsim tbsim -R

# Which libraries an IP needs: look at <ip>/sim/... or the generated export_simulation script;
# e.g. an AXI VIP design needs
xelab -L xilinx_vip -L axi_vip_v1_1_16 -L smartconnect_v1_0 -L unisims_ver ... work.tb   (library versions differ per release)

add_condition -name stop_on_err {/tb/dut/err_flag == 1} {puts "error at [current_time]"; stop}
add_condition {/tb/dut/fifo_full == 1} {incr ::full_events}
run all
puts "fifo full events: $::full_events"
report_conditions
remove_conditions -all

// tb_top.sv
`include "uvm_macros.svh"
import uvm_pkg::*;
module tb_top; axi_if vif(clk); dut u_dut(.axi(vif)); initial begin uvm_config_db#(virtual axi_if)::set(null, "*", "vif", vif); run_test(); end endmodule

# regression loop collecting one database per seed then merging
foreach seed {1 2 3} { exec xsim tb_cov -R -sv_seed $seed -tclbatch run.tcl }
exec xcrg -report_format html -dir ./coverage

-- VHDL top instantiating a Verilog module: declare a component with matching port types
component axis_filter is generic (TAPS : integer := 16); port (aclk : in std_logic; s_tdata : in std_logic_vector(31 downto 0); ...); end component;
// Verilog testbench instantiating the VHDL top
top_vhdl #(.DATA_WIDTH(32)) u_dut (.clk(clk), .din(din), .dout(dout));
